    print(i["File"].split("/")[-1], i["StartLine"], i["RuleID"], "secret_len", len(secret), "match_len", len(match))
    for n in needles:
        print(" ", n[:24], "in_secret", n in secret, "in_match", n in match)
    # shape only
    def shape(s):
        out=[]
        for ch in s[:80]:
            if ch.isalpha(): out.append("A")
            elif ch.isdigit(): out.append("9")
            elif ch.isspace(): out.append("_")
            else: out.append(ch)
        return "".join(out)
    print(" secret_shape", shape(secret))
    print(" match_shape", shape(match))
